// Normalise la réponse de La Bonne Alternance (offres + candidatures spontanées)
const out = [];
for (const item of $input.all()) {
  const data = item.json;
  if (!data || data.error) continue; // l'API a échoué : on ignore cette source

  for (const o of data.jobs || []) {
    const id = o.identifier?.id || o.apply?.url;
    if (!id) continue;
    out.push({ json: {
      id: 'lba-' + id,
      source: 'La Bonne Alternance',
      type: 'Offre',
      titre: o.offer?.title || 'Sans titre',
      entreprise: o.workplace?.name || o.workplace?.legal_name || 'Non renseigné',
      secteur: o.workplace?.domain?.naf?.label || o.domain?.naf?.label || 'Non renseigné',
      adresse: o.workplace?.location?.address || 'Non renseigné',
      description: o.offer?.description || 'Pas de description.',
      url: o.apply?.url || 'Non renseigné',
    }});
  }

  for (const r of data.recruiters || []) {
    const id = r.identifier?.id || r.workplace?.siret || r.apply?.url;
    if (!id) continue;
    const nom = r.workplace?.name || r.workplace?.legal_name || 'Entreprise inconnue';
    out.push({ json: {
      id: 'lba-rec-' + id,
      source: 'La Bonne Alternance',
      type: 'Candidature spontanée',
      titre: 'Candidature spontanée — ' + nom,
      entreprise: nom,
      secteur: r.workplace?.domain?.naf?.label || r.domain?.naf?.label || 'Non renseigné',
      adresse: r.workplace?.location?.address || 'Non renseigné',
      description: "Entreprise susceptible de recruter en alternance (pas d'offre publiée). Juge selon le secteur d'activité.",
      url: r.apply?.url || 'Non renseigné',
    }});
  }
}
return out;

// Normalise la réponse Google Jobs (SerpAPI)
const out = [];
for (const item of $input.all()) {
  const data = item.json;
  if (!data || data.error) continue;

  for (const o of data.jobs_results || []) {
    const url = o.apply_options?.[0]?.link || o.share_link || o.source_link;
    const id = o.job_id || url;
    if (!id) continue;
    out.push({ json: {
      id: 'gj-' + id,
      source: 'Google Jobs',
      type: 'Offre',
      titre: o.title || 'Sans titre',
      entreprise: o.company_name || 'Non renseigné',
      secteur: 'Non renseigné',
      adresse: o.location || 'Non renseigné',
      description: o.description || 'Pas de description.',
      url: url || 'Non renseigné',
    }});
  }
}
return out;

// Ne garde que les offres jamais vues.
// ⚠️ La mémoire (staticData) n'est enregistrée que lors des exécutions automatiques
// (workflow actif), pas lors des tests manuels avec "Execute workflow".
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenIds) staticData.seenIds = [];

const dejaVus = new Set(staticData.seenIds);
const nouvelles = [];

for (const item of $input.all()) {
  const o = item.json;
  if (!o.id || dejaVus.has(o.id)) continue; // ignore les doublons et les éléments vides
  dejaVus.add(o.id);
  staticData.seenIds.push(o.id);

  nouvelles.push({ json: {
    ...o,
    // on limite la taille pour ne pas surcharger le modèle local
    description: String(o.description).slice(0, 1500),
  }});
}

// On garde seulement les 1000 derniers IDs
if (staticData.seenIds.length > 1000) {
  staticData.seenIds = staticData.seenIds.slice(-1000);
}

console.log(`${nouvelles.length} nouvelle(s) offre(s) — ${staticData.seenIds.length} IDs en mémoire`);
return nouvelles;

