// Récupère l'offre en cours dans la boucle + la réponse de l'IA
const offre = $('Loop Over Items').first().json;
const texte = String($input.first().json.text || '');

let ia;
try {
  const debut = texte.indexOf('{');
  const fin = texte.lastIndexOf('}');
  if (debut === -1 || fin === -1) throw new Error('Pas de JSON');
  ia = JSON.parse(texte.substring(debut, fin + 1));
  ia.score = Number(ia.score) || 0;
  ia.raison = String(ia.raison || '').slice(0, 500);
} catch (e) {
  ia = { score: 0, raison: 'Erreur de formatage IA. Réponse brute : ' + texte.slice(0, 300) };
}

return [{ json: { ...offre, ia } }];
